// Run: tsx exemplar.ts

const NUCLEOTIDES = ["A", "C", "G", "T"];

/**
 * BFS over the implicit gene graph: states are bank genes, edges are
 * single-nucleotide changes. Candidates are generated by substitution
 * (8 positions x 3 other letters) and filtered through the bank set —
 * never by comparing all bank pairs. Deleting a gene from the set at
 * enqueue time is the visited mark. The answer counts edges (mutations).
 * O(B) time with constant factor 8 x 4, O(B) space.
 */
export function minMutation(startGene: string, endGene: string, bank: string[]): number {
  if (startGene === endGene) return 0;
  const valid = new Set(bank);
  if (!valid.has(endGene)) return -1;
  const queue: [string, number][] = [[startGene, 0]];
  let head = 0;
  valid.delete(startGene); // never revisit the start
  while (head < queue.length) {
    const [gene, mutations] = queue[head++];
    for (let i = 0; i < gene.length; i++) {
      for (const ch of NUCLEOTIDES) {
        if (ch === gene[i]) continue;
        const next = gene.slice(0, i) + ch + gene.slice(i + 1);
        if (!valid.has(next)) continue;
        if (next === endGene) return mutations + 1;
        valid.delete(next); // visited-on-push
        queue.push([next, mutations + 1]);
      }
    }
  }
  return -1;
}

/**
 * Identical BFS over the word graph, with two differences: the alphabet is
 * a-z, and the answer counts WORDS in the chain (edges + 1), so the start
 * distance is 1. The word set doubles as the visited set — a word is
 * deleted the moment it is enqueued, which BFS makes safe: the first route
 * to any word is already a shortest one.
 * O(N * L^2 * 26) time, O(N * L) space.
 */
export function ladderLength(beginWord: string, endWord: string, wordList: string[]): number {
  const words = new Set(wordList);
  if (!words.has(endWord)) return 0;
  const queue: [string, number][] = [[beginWord, 1]];
  let head = 0;
  words.delete(beginWord);
  while (head < queue.length) {
    const [word, length] = queue[head++];
    for (let i = 0; i < word.length; i++) {
      for (let code = 97; code <= 122; code++) { // 'a'..'z'
        const ch = String.fromCharCode(code);
        if (ch === word[i]) continue;
        const next = word.slice(0, i) + ch + word.slice(i + 1);
        if (!words.has(next)) continue;
        if (next === endWord) return length + 1;
        words.delete(next); // visited-on-push
        queue.push([next, length + 1]);
      }
    }
  }
  return 0;
}

function main(): void {
  console.log(minMutation("AACCGGTT", "AACCGGTA", ["AACCGGTA"])); // 1
  console.log(minMutation("AACCGGTT", "AAACGGTA", ["AACCGGTA", "AACCGCTA", "AAACGGTA"])); // 2
  console.log(ladderLength("hit", "cog", ["hot", "dot", "dog", "lot", "log", "cog"])); // 5
  console.log(ladderLength("hit", "cog", ["hot", "dot", "dog", "lot", "log"])); // 0
}

main();
